let TYPES=[],TYPE_ZH={},C={},TYPE_COLORS={},NAME_ZH={},ITEM_ZH={},MOVE_ZH={},ABILITY_ZH={},NATURE_ZH={},NATURES=[],IMPLEMENTED_ITEMS=[],MOVES=[],STAT_KEYS=[],STAT_LABELS={},DEFAULT_POINTS={attacker:{},defender:{}};

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let chineseAliases = {};
function speciesKey(name){
  return String(name||'').toLowerCase().replace(/^mega\s+/,'').replace(/^(alolan|hisuian|galarian|paldean)\s+/,'').replace(/\s*\[.*$/,'').replace(/\s+(male|female)$/,'').replace(/\s+z$/,'').replace(/[.'’]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
}
const zhName = name => NAME_ZH[name] || chineseAliases[speciesKey(name)] || name;
function localizedFormName(title,baseName){
  if(NAME_ZH[title]) return NAME_ZH[title];
  const baseZh=zhName(baseName);
  if(title===baseName) return baseZh;
  if(/^Mega\s/.test(title)){
    const clean=title.replace(/^Mega\s+/,'');
    const suffix=clean.toLowerCase().startsWith(String(baseName).toLowerCase())?clean.slice(String(baseName).length).trim():'';
    return `超级${baseZh}${suffix}`;
  }
  const regional=title.match(/\[(Hisuian|Alolan|Galarian|Paldean)[^\]]*\]/i);
  if(regional){const label={hisuian:'洗翠',alolan:'阿罗拉',galarian:'伽勒尔',paldean:'帕底亚'}[regional[1].toLowerCase()];return `${baseZh}（${label}形态）`;}
  return baseZh!==baseName?`${baseZh} · ${title}`:title;
}
const zhItem = name => ITEM_ZH[name] || name || '暂无';
const zhMove = name => MOVE_ZH[name] || name || '暂无';
const zhAbility = name => ABILITY_ZH[name] || name || '暂无';
const zhNature = name => NATURE_ZH[name] || name || '暂无';
const typeColor = t => TYPE_COLORS[t] || '#9ba3a8';
const pct = entry => entry?.percentage ? ` ${entry.percentage}` : '';

let store = {meta:null,catalog:[],calculator:[],items:[]};
const API_REVISION='12';
const dataCache={usage:{},calculator:null};
const dataRequests={usage:{},calculator:null};
let commonReady=false;
let ranking = [], selectedRank = 0;
let calcState;

function hydrateStatic(data){TYPES=data.types;TYPE_ZH=data.typeZh;C=data.typeChart;TYPE_COLORS=data.typeColors;NAME_ZH=data.nameZh;ITEM_ZH=data.itemZh;MOVE_ZH=data.moveZh;ABILITY_ZH=data.abilityZh;NATURE_ZH=data.natureZh;NATURES=data.natures;IMPLEMENTED_ITEMS=data.implementedItems;MOVES=data.moves;STAT_KEYS=data.statKeys;STAT_LABELS=data.statLabels;DEFAULT_POINTS=data.defaultPoints;}
function createCalcState(){return {attacker:{pokemonIndex:0,pokemonSlug:null,nature:'Adamant',item:'No Item',points:{...DEFAULT_POINTS.attacker}},defender:{pokemonIndex:1,pokemonSlug:null,nature:'Bold',item:'No Item',points:{...DEFAULT_POINTS.defender}},battle:{format:'Doubles',target:'single',weather:'none',terrain:'none',attackerGrounded:'auto',defenderGrounded:'auto',reflect:false,lightScreen:false,auroraVeil:false,burn:false,critical:false,helpingHand:false,friendGuard:false}};}

function setStatus(message,kind=''){const box=$('#update-status');box.textContent=message;box.className=`update-status ${kind}`.trim();}
function dateText(value){if(!value)return '时间未知';try{return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Shanghai'}).format(new Date(value));}catch{return value;}}
function applyMeta(meta){store.meta=meta;if(!meta)return;$('#season-label').textContent=`赛季 ${meta.season||'未知'}`;$('#snapshot-label').textContent=`每周对战数据 / ${meta.season||'未知赛季'}`;$('#roster-count').textContent=meta.rosterCount||'—';$('#data-season').textContent=meta.season||'未知';$('#data-date').textContent=dateText(meta.generatedAt);$('#footer-snapshot').textContent=`${meta.season||'未知'} · ${dateText(meta.generatedAt)}`;}
function sourceLabel(){return store.meta?.source?.startsWith('PokéChamp')?'PokéChamp DB':'Battle Data';}
function translationNotice(meta=store.meta){const missing=meta?.translationCoverage?.missingTotal||0;return missing?`；另有 ${missing} 个新名称暂缺可靠中文译名，当前临时显示英文`:'';}
function showUsageSkeleton(){$('#ranking-list').innerHTML=Array.from({length:8},()=>'<div class="skeleton-row" aria-hidden="true"></div>').join('');$('#config-panel').innerHTML='<div class="skeleton-panel" aria-hidden="true"></div>';}
function showCalcSkeleton(){['atk','def'].forEach(prefix=>{const trigger=$(`#${prefix}-picker-trigger`);trigger.disabled=true;trigger.innerHTML='<span class="picker-selection-copy"><b>正在加载图鉴…</b><small>只获取计算器所需数据</small></span>';});}
function currentView(){return $('.view.active')?.id||'usage';}
function clearViewError(view){$(`#${view} .view-error`)?.remove();}
function showViewError(view,message,retry){clearViewError(view);const box=document.createElement('div');box.className='view-error';box.setAttribute('role','alert');box.textContent=message;const button=document.createElement('button');button.type='button';button.textContent='重试';button.onclick=()=>{box.remove();retry();};box.append(button);$(`#${view} .page-head`).after(box);}
async function fetchJSON(url,options){const response=await fetch(url,{headers:{Accept:'application/json'},...options});const payload=await response.json();if(!response.ok)throw new Error(payload.error||`HTTP ${response.status}`);return payload;}
function applyUsage(payload,{fromCache=false}={}){const format=payload.format;store.catalog=payload.catalog||[];applyMeta(payload.meta||store.meta);ranking=store.catalog.slice().sort((a,b)=>a.battles[format].position-b.battles[format].position);$('#format-label').textContent=format==='Doubles'?'双打':'单打';$('#top-pokemon').textContent=ranking[0]?.displayName||'暂无';$('#top-format').textContent=format==='Doubles'?'双打使用第 1':'单打使用第 1';renderRanking($('#usage-search').value);selectedRank=Math.min(selectedRank,Math.max(0,ranking.length-1));if(ranking.length)selectConfig(selectedRank);else $('#config-panel').innerHTML='<div class="panel-empty">当前形式暂无可用排名。</div>';if(store.meta?.season==='M5')setStatus(`镜像最新快照仍为 M5（${dateText(store.meta.generatedAt)}），等待源站发布新赛季后可再次点击更新。`,'warn');else setStatus(`${fromCache?'已读取缓存':'已从 SQLite 读取'}：${store.meta?.season||'未知赛季'}，生成于 ${dateText(store.meta?.generatedAt)}${translationNotice()}。`,store.meta?.translationCoverage?.missingTotal?'warn':'success');clearViewError('usage');}
async function usagePayload(format,{force=false}={}){if(!force&&dataCache.usage[format])return dataCache.usage[format];if(!force&&dataRequests.usage[format])return dataRequests.usage[format];const request=fetchJSON(`/api/usage?format=${encodeURIComponent(format)}&v=${API_REVISION}`).then(payload=>(dataCache.usage[format]=payload)).finally(()=>{dataRequests.usage[format]=null;});dataRequests.usage[format]=request;return request;}
async function loadUsage({force=false,prefetch=false}={}){const format=$('#format-select').value;if(!prefetch){showUsageSkeleton();setStatus('正在读取当前对战形式前 50 名…');}const cached=!force&&!!dataCache.usage[format];const payload=await usagePayload(format,{force});if(!prefetch&&$('#format-select').value===format)applyUsage(payload,{fromCache:cached});return payload;}
function applyCalculator(payload){applyMeta(payload.meta||store.meta);chineseAliases={...(payload.aliases||{})};store.calculator=payload.calculator||[];store.items=payload.items||[];refreshCalculator();clearViewError('calc');}
async function calculatorPayload({force=false}={}){if(!force&&dataCache.calculator)return dataCache.calculator;if(!force&&dataRequests.calculator)return dataRequests.calculator;const request=fetchJSON(`/api/calculator?v=${API_REVISION}`).then(payload=>(dataCache.calculator=payload)).finally(()=>{dataRequests.calculator=null;});dataRequests.calculator=request;return request;}
async function loadCalculator({force=false,prefetch=false}={}){const payload=await calculatorPayload({force});if(!prefetch)applyCalculator(payload);return payload;}
async function ensureViewData(view,{force=false}={}){if(!commonReady)return;try{if(view==='usage')await loadUsage({force});else if(view==='calc')await loadCalculator({force});else clearViewError('types');}catch(error){console.error(error);if(view==='usage')setStatus(`读取失败：${error.message}`,'error');showViewError(view,`无法读取该页面数据：${error.message}`,()=>ensureViewData(view,{force:true}));}}
function canPrefetch(){const connection=navigator.connection||navigator.mozConnection||navigator.webkitConnection;return !connection?.saveData&&!['slow-2g','2g'].includes(connection?.effectiveType);}
function schedulePrefetch(){if(!canPrefetch())return;const run=()=>{const other=$('#format-select').value==='Doubles'?'Singles':'Doubles';usagePayload(other).catch(()=>{});calculatorPayload().catch(()=>{});};if('requestIdleCallback'in window)requestIdleCallback(run,{timeout:3500});else setTimeout(run,1800);}
async function updateData({silent=false}={}){
  const button=$('#refresh-data');button.disabled=true;button.classList.add('loading');if(!silent)setStatus('正在更新赛季数据；主数据源不可用时将自动切换备用镜像…');
  try{const payload=await fetchJSON('/api/refresh',{method:'POST'});applyMeta(payload.meta);dataCache.usage={};dataCache.calculator=null;dataRequests.usage={};dataRequests.calculator=null;store.catalog=[];store.calculator=[];store.items=[];await ensureViewData(currentView(),{force:true});if(currentView()!=='usage')setStatus(`更新完成：${payload.meta?.season||'未知赛季'}${translationNotice(payload.meta)}。`,payload.meta?.translationCoverage?.missingTotal?'warn':'success');schedulePrefetch();}
  catch(error){console.error(error);setStatus(`更新失败：${error.message}。SQLite 中的上次成功数据已保留；请稍后重试。`,'error');}
  finally{button.disabled=false;button.classList.remove('loading');}
}

function monImage(m,large=false){return `<span class="avatar-shell ${large?'large':''}"><img class="avatar-img" src="${esc(m.sprite)}" alt="${esc(m.displayName)}图标" loading="lazy" decoding="async"><span class="avatar-fallback" aria-hidden="true">◉</span></span>`;}
function bindImageFallbacks(root=document){root.querySelectorAll('.avatar-img').forEach(img=>img.addEventListener('error',()=>img.parentElement.classList.add('image-missing'),{once:true}));}
let configReturnFocus=null;
const mobileConfigQuery=window.matchMedia('(max-width:720px)');
function openConfigDrawer(trigger){if(!mobileConfigQuery.matches)return;configReturnFocus=trigger||document.activeElement;const panel=$('#config-panel'),backdrop=$('#config-backdrop');panel.classList.add('mobile-open');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','宝可梦常用配置');backdrop.hidden=false;document.body.classList.add('config-drawer-open');requestAnimationFrame(()=>panel.querySelector('.config-close')?.focus());}
function closeConfigDrawer({returnFocus=true}={}){const panel=$('#config-panel'),backdrop=$('#config-backdrop');if(!panel.classList.contains('mobile-open'))return;panel.classList.remove('mobile-open');panel.removeAttribute('role');panel.removeAttribute('aria-modal');panel.removeAttribute('aria-label');backdrop.hidden=true;document.body.classList.remove('config-drawer-open');if(returnFocus&&configReturnFocus?.isConnected)configReturnFocus.focus({preventScroll:true});configReturnFocus=null;}
function trapConfigFocus(event){if(event.key==='Escape'){event.preventDefault();closeConfigDrawer();return;}if(event.key!=='Tab')return;const focusable=$$('#config-panel button:not([disabled]),#config-panel a[href]');if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
function renderRanking(filter=''){
  const q=filter.trim().toLowerCase(),format=$('#format-select').value;
  const list=ranking.filter(m=>[m.name,m.displayName,m.slug].filter(Boolean).join(' ').toLowerCase().includes(q));
  $('#empty-ranking').hidden=!!list.length;
  $('#ranking-list').innerHTML=list.map(m=>{const realIndex=ranking.indexOf(m),b=m.battles[format],top=b.top||{};return `<button class="rank-row" data-index="${realIndex}"><span class="mon-id"><b class="rank ${b.position<=3?'top':''}">${String(b.position).padStart(2,'0')}</b>${monImage(m)}<span><b class="mon-name">${esc(m.displayName)}</b><span class="types">${m.types.map(t=>`<i class="type-pill" style="color:${typeColor(t)}">${esc(t)}</i>`).join('')}</span></span></span><span class="data-cell"><b>${esc(zhItem(top.held_item?.name))}</b><small>${esc(top.held_item?.percentage||'—')}</small></span><span class="data-cell"><b>${esc(zhMove(top.move?.name))}</b><small>${esc(top.move?.percentage||'—')}</small></span><span class="data-cell"><b>${esc(zhNature(top.stat_alignment?.name))}</b><small>${esc(top.stat_alignment?.percentage||'—')}</small></span><span class="source-chip">${esc(sourceLabel())}</span></button>`;}).join('');
  $$('.rank-row').forEach(button=>button.addEventListener('click',()=>selectConfig(+button.dataset.index,{openMobile:true,trigger:button})));bindImageFallbacks($('#ranking-list'));
}
function topToken(entry,translator){if(!entry?.name)return '<span class="config-token muted-token">暂无公开数据</span>';return `<span class="config-token">${esc(translator(entry.name))}${entry.percentage?` <b>${esc(entry.percentage)}</b>`:''}</span>`;}
function selectConfig(index,{openMobile=false,trigger=null}={}){
  const m=ranking[index];if(!m)return;selectedRank=index;const format=$('#format-select').value,b=m.battles[format],top=b.top||{},values=b.values||{};$$('.rank-row').forEach(r=>r.classList.toggle('active',+r.dataset.index===index));
  const moves=(values.move||[]).slice(0,4),items=(values.held_item||[]).slice(0,3),abilities=(values.ability||[]).slice(0,2);const spreadText=top.stat_points?`生命 ${top.stat_points.hp_points} / 攻击 ${top.stat_points.attack_points} / 防御 ${top.stat_points.defense_points} / 特攻 ${top.stat_points.sp_atk_points} / 特防 ${top.stat_points.sp_def_points} / 速度 ${top.stat_points.speed_points}`:(values.stat_points?.[0]||'暂无公开数据');
  $('#config-panel').innerHTML=`<button class="config-close" type="button" aria-label="关闭配置">关闭</button><div class="config-drag-handle" aria-hidden="true"></div><div class="config-identity">${monImage(m,true)}<div><span class="config-rank">使用排名 ${String(b.position).padStart(2,'0')}</span><h2>${esc(m.displayName)}</h2><div class="types">${m.types.map(t=>`<i class="type-pill" style="color:${typeColor(t)}">${esc(t)}</i>`).join('')}</div></div></div><p class="config-usage">${format==='Doubles'?'双打':'单打'} · ${esc(store.meta.season)} · ${esc(sourceLabel())} 镜像</p><div class="config-block"><div class="config-label"><span>特性</span><span>首选比例</span></div><div class="config-list">${abilities.length?abilities.map((x,i)=>i===0?topToken(top.ability,zhAbility):`<span class="config-token">${esc(zhAbility(x))}</span>`).join(''):topToken(top.ability,zhAbility)}</div></div><div class="config-block"><div class="config-label"><span>携带道具</span><span>前三</span></div><div class="config-list">${items.length?items.map((x,i)=>i===0?topToken(top.held_item,zhItem):`<span class="config-token">${esc(zhItem(x))}</span>`).join(''):topToken(top.held_item,zhItem)}</div></div><div class="config-block"><div class="config-label"><span>常用招式</span><span>前四</span></div><div class="config-list">${moves.length?moves.map((x,i)=>i===0?topToken(top.move,zhMove):`<span class="config-token">${esc(zhMove(x))}</span>`).join(''):'<span class="config-token muted-token">暂无公开数据</span>'}</div></div><div class="config-block"><div class="config-label"><span>性格 / 能力点</span><span>${esc(zhNature(top.stat_alignment?.name))}${esc(pct(top.stat_alignment))}</span></div><div class="ev-spread">${esc(spreadText)}</div></div><button class="copy-btn" id="copy-config">复制 Champions 配置</button>`;
  $('#config-panel .config-close').onclick=()=>closeConfigDrawer();if(openMobile)openConfigDrawer(trigger);
  bindImageFallbacks($('#config-panel'));$('#copy-config').onclick=()=>{const text=`${m.displayName}｜携带：${zhItem(top.held_item?.name)}\n特性：${zhAbility(top.ability?.name)}\n性格：${zhNature(top.stat_alignment?.name)}\n能力点：${spreadText}\n- ${moves.map(zhMove).join('\n- ')}`;navigator.clipboard?.writeText(text);$('#copy-config').textContent='已复制 ✓';setTimeout(()=>{const btn=$('#copy-config');if(btn)btn.textContent='复制 Champions 配置';},1200);};
}

function navTo(id){closeConfigDrawer({returnFocus:false});$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===id));history.replaceState(null,'',`#${id}`);window.scrollTo({top:0,behavior:'smooth'});void ensureViewData(id);}
function mult(a,d){return C[a]?.[d]??1;}
function setupTypes(){const opts=TYPES.map(t=>`<option>${t}</option>`).join('');$('#def-type-1').innerHTML=opts;$('#def-type-2').innerHTML='<option value="">无</option>'+opts;$('#def-type-1').value='龙';$('#def-type-2').value='地面';const grid=['<div class="matrix-cell"></div>',...TYPES.map(t=>`<div class="matrix-cell header" title="防守：${t}">${t}</div>`)];TYPES.forEach(a=>{grid.push(`<div class="matrix-cell row-head" style="border-left:3px solid ${typeColor(a)}">${a}</div>`);TYPES.forEach(d=>{const v=mult(a,d);grid.push(`<div class="matrix-cell val-${String(v).replace('.','')}" title="${a} → ${d}：${v}×">${v===1?'·':v+'×'}</div>`);});});$('#type-matrix').innerHTML=grid.join('');$('#def-type-1').onchange=renderTypeSummary;$('#def-type-2').onchange=renderTypeSummary;renderTypeSummary();}
function renderTypeSummary(){const ds=[$('#def-type-1').value,$('#def-type-2').value].filter(Boolean),groups={weak:[],resist:[],immune:[]};TYPES.forEach(a=>{const v=ds.reduce((n,d)=>n*mult(a,d),1);if(v===0)groups.immune.push(a);else if(v>1)groups.weak.push(`${a} ${v}×`);else if(v<1)groups.resist.push(`${a} ${v}×`);});const values=items=>items.length?items.map(item=>`<strong>${esc(item)}</strong>`).join(''):'<strong class="summary-empty">无</strong>';$('#type-summary').innerHTML=`<div class="summary-group weak"><b>弱点</b><span class="summary-values">${values(groups.weak)}</span></div><div class="summary-group resist"><b>抗性</b><span class="summary-values">${values(groups.resist)}</span></div><div class="summary-group immune"><b>免疫</b><span class="summary-values">${values(groups.immune)}</span></div>`;}

function fillSelect(id,arr,label=x=>x,value=(x,i)=>i){$(id).innerHTML=arr.map((x,i)=>`<option value="${esc(value(x,i))}">${esc(label(x))}</option>`).join('');}
function natureMod(name,stat){const mods={Adamant:['atk','spa'],Jolly:['spe','spa'],Modest:['spa','atk'],Timid:['spe','atk'],Bold:['def','atk'],Impish:['def','spa'],Careful:['spd','spa'],Calm:['spd','atk'],Brave:['atk','spe'],Quiet:['spa','spe'],Relaxed:['def','spe'],Sassy:['spd','spe']};const pair=mods[name];if(!pair)return 1;return stat===pair[0]?1.1:stat===pair[1]?.9:1;}
function championStat(base,points,nature=1){return Math.max(1,Math.floor((Number(base)+Number(points))*nature));}
function itemMod(item,move,typeEffect){if(item==='Life Orb')return 1.3;if(item==='Choice Specs'&&move.category==='特殊')return 1.5;if(item==='Choice Band'&&move.category==='物理')return 1.5;if(item==='Expert Belt'&&typeEffect>1)return 1.2;if(item==='Muscle Band'&&move.category==='物理')return 1.1;if(item==='Wise Glasses'&&move.category==='特殊')return 1.1;if(item==='Normal Gem'&&move.type==='一般')return 1.3;const boosts={水:'Mystic Water',火:'Charcoal',电:'Magnet',恶:'Black Glasses',钢:'Metal Coat',草:'Miracle Seed',冰:'Never-Melt Ice',龙:'Dragon Fang',毒:'Poison Barb',飞行:'Sharp Beak',虫:'Silver Powder',幽灵:'Spell Tag',超能力:'Twisted Spoon',格斗:'Black Belt',岩石:'Hard Stone',一般:'Silk Scarf',妖精:'Fairy Feather',地面:'Soft Sand'};return boosts[move.type]===item?1.2:1;}

const pickerState={attacker:{open:false,query:'',active:0,results:[]},defender:{open:false,query:'',active:0,results:[]}};
const sidePrefix=side=>side==='attacker'?'atk':'def';
function currentCalcMon(side){return store.calculator[calcState[side].pokemonIndex];}
function pokemonSearchText(mon){return [mon?.name,mon?.baseName,mon?.displayName,mon?.baseDisplayName,mon?.slug].filter(Boolean).join(' ').toLowerCase();}
function renderPickerSelection(side){
  const prefix=sidePrefix(side),mon=currentCalcMon(side),trigger=$(`#${prefix}-picker-trigger`);if(!trigger)return;
  if(!mon){trigger.innerHTML='<span class="picker-selection-copy"><b>等待图鉴数据</b><small>载入后可搜索</small></span>';trigger.disabled=true;return;}
  trigger.disabled=false;trigger.innerHTML=`<span class="picker-selection">${monImage(mon)}<span class="picker-selection-copy"><b>${esc(mon.displayName)}</b></span><span class="types">${mon.types.map(t=>`<i class="type-pill" style="color:${typeColor(t)}">${esc(t)}</i>`).join('')}</span><span class="picker-chevron">⌄</span></span>`;bindImageFallbacks(trigger);
}
function filteredPokemon(side){const q=pickerState[side].query.trim().toLowerCase();return store.calculator.map((mon,index)=>({mon,index})).filter(x=>!q||pokemonSearchText(x.mon).includes(q));}
function renderPickerList(side){
  const prefix=sidePrefix(side),state=pickerState[side],results=filteredPokemon(side);state.results=results;state.active=Math.max(0,Math.min(state.active,results.length-1));
  const list=$(`#${prefix}-pokemon-list`);if(!list)return;
  list.innerHTML=results.length?results.map((x,i)=>`<button type="button" id="${prefix}-option-${i}" class="picker-option ${i===state.active?'active':''}" data-index="${x.index}" role="option" aria-selected="${x.index===calcState[side].pokemonIndex}" tabindex="-1">${monImage(x.mon)}<span class="picker-option-copy"><b>${esc(x.mon.displayName)}</b></span><span class="types">${x.mon.types.map(t=>`<i class="type-pill" style="color:${typeColor(t)}">${esc(t)}</i>`).join('')}</span></button>`).join(''):'<div class="picker-empty">没有匹配的宝可梦或形态</div>';
  list.querySelectorAll('.picker-option').forEach(button=>button.addEventListener('click',()=>selectPokemon(side,+button.dataset.index)));bindImageFallbacks(list);
  const input=$(`#${prefix}-pokemon-search`);if(results.length)input.setAttribute('aria-activedescendant',`${prefix}-option-${state.active}`);else input.removeAttribute('aria-activedescendant');
}
function openPicker(side){
  const other=side==='attacker'?'defender':'attacker';closePicker(other);const prefix=sidePrefix(side),state=pickerState[side];state.open=true;state.query='';state.active=0;$(`#${prefix}-picker-popover`).hidden=false;$(`#${prefix}-picker-trigger`).setAttribute('aria-expanded','true');const input=$(`#${prefix}-pokemon-search`);input.value='';renderPickerList(side);requestAnimationFrame(()=>input.focus());
}
function closePicker(side,returnFocus=false){const prefix=sidePrefix(side),popover=$(`#${prefix}-picker-popover`);if(!popover)return;pickerState[side].open=false;popover.hidden=true;$(`#${prefix}-picker-trigger`).setAttribute('aria-expanded','false');if(returnFocus)$(`#${prefix}-picker-trigger`).focus();}
function movePickerActive(side,delta){const state=pickerState[side];if(!state.results.length)return;state.active=(state.active+delta+state.results.length)%state.results.length;renderPickerList(side);$(`#${sidePrefix(side)}-option-${state.active}`)?.scrollIntoView({block:'nearest'});}
function selectPokemon(side,index){const mon=store.calculator[index];if(!mon)return;calcState[side].pokemonIndex=index;calcState[side].pokemonSlug=mon.slug;$(`#${sidePrefix(side)}-pokemon`).value=index;renderPickerSelection(side);closePicker(side,true);renderStats(side);if(side==='attacker')updateMoveOptions();calculate();}
function setupPicker(side){
  const prefix=sidePrefix(side),trigger=$(`#${prefix}-picker-trigger`),input=$(`#${prefix}-pokemon-search`);trigger.addEventListener('click',()=>pickerState[side].open?closePicker(side):openPicker(side));trigger.addEventListener('keydown',event=>{if(['Enter',' ','ArrowDown'].includes(event.key)){event.preventDefault();openPicker(side);}});input.addEventListener('input',()=>{pickerState[side].query=input.value;pickerState[side].active=0;renderPickerList(side);});input.addEventListener('keydown',event=>{if(event.key==='ArrowDown'){event.preventDefault();movePickerActive(side,1);}else if(event.key==='ArrowUp'){event.preventDefault();movePickerActive(side,-1);}else if(event.key==='Enter'&&pickerState[side].results.length){event.preventDefault();selectPokemon(side,pickerState[side].results[pickerState[side].active].index);}else if(event.key==='Escape'){event.preventDefault();closePicker(side,true);}});
}

function pointsTotal(side){return STAT_KEYS.reduce((sum,key)=>sum+calcState[side].points[key],0);}
function renderStatEditors(){
  ['attacker','defender'].forEach(side=>{const prefix=sidePrefix(side);$(`#${prefix}-stats`).innerHTML=STAT_KEYS.map(key=>`<div class="stat-edit" id="${prefix}-stat-row-${key}"><div class="stat-edit-info"><b>${STAT_LABELS[key]}</b><strong id="${prefix}-final-${key}">—</strong></div><input id="${prefix}-point-${key}-range" type="range" min="0" max="32" step="1" value="${calcState[side].points[key]}" aria-label="${side==='attacker'?'攻击方':'防守方'}${STAT_LABELS[key]}能力点"><input id="${prefix}-point-${key}-number" type="number" min="0" max="32" step="1" value="${calcState[side].points[key]}" aria-label="${side==='attacker'?'攻击方':'防守方'}${STAT_LABELS[key]}能力点数值"></div>`).join('');});
}
function setPoint(side,key,rawValue){
  const requested=Math.max(0,Math.min(32,Math.round(Number(rawValue)||0))),others=pointsTotal(side)-calcState[side].points[key],allowed=Math.max(0,Math.min(32,66-others)),value=Math.min(requested,allowed),prefix=sidePrefix(side);calcState[side].points[key]=value;$(`#${prefix}-point-${key}-range`).value=value;$(`#${prefix}-point-${key}-number`).value=value;if(value!==requested){const row=$(`#${prefix}-stat-row-${key}`);row.classList.remove('capped');void row.offsetWidth;row.classList.add('capped');}renderStats(side);calculate();
}
function renderStats(side){
  const mon=currentCalcMon(side),prefix=sidePrefix(side),nature=calcState[side].nature,total=pointsTotal(side),totalNode=$(`#${prefix}-points-total`);totalNode.textContent=`${total} / 66 · 剩余 ${66-total}`;totalNode.classList.toggle('full',total===66);STAT_KEYS.forEach(key=>{const node=$(`#${prefix}-final-${key}`);if(node)node.textContent=mon?championStat(mon.stats[key],calcState[side].points[key],key==='hp'?1:natureMod(nature,key)):'—';});
}
function setupStatInputs(){['attacker','defender'].forEach(side=>{const prefix=sidePrefix(side);STAT_KEYS.forEach(key=>{$(`#${prefix}-point-${key}-range`).addEventListener('input',event=>setPoint(side,key,event.target.value));$(`#${prefix}-point-${key}-number`).addEventListener('input',event=>setPoint(side,key,event.target.value));});});}
function resetPoints(side){calcState[side].points={...DEFAULT_POINTS[side]};const prefix=sidePrefix(side);STAT_KEYS.forEach(key=>{$(`#${prefix}-point-${key}-range`).value=calcState[side].points[key];$(`#${prefix}-point-${key}-number`).value=calcState[side].points[key];});renderStats(side);calculate();}

function updateMoveOptions(){const mon=currentCalcMon('attacker'),previous=$('#move-select').value,known=new Set(mon?.learnableMoves||[]),moves=mon?MOVES.filter(m=>known.has(m.name)):[];fillSelect('#move-select',moves,m=>{const shown=moveInWeather(m,calcState?.battle?.weather||'none');return `${zhMove(m.name)} · ${shown.type} · 威力 ${shown.power??'随条件变化'}`;},m=>m.name);if(moves.some(m=>m.name===previous))$('#move-select').value=previous;}
function isGrounded(mon,item,setting){if(setting==='yes')return true;if(setting==='no')return false;return !mon.types.includes('飞行')&&item!=='Air Balloon';}
function moveInWeather(move,weather){
  const weatherTypes={sun:'火',rain:'水',sand:'岩石',snow:'冰'};
  if(move.name!=='Weather Ball'||!weatherTypes[weather])return {...move};
  return {...move,type:weatherTypes[weather],power:Number(move.power)*2,weatherBallChanged:true};
}
function renderFactors(factors){$('#calc-factors').innerHTML=factors.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(f.value)}${f.note?` <small>${esc(f.note)}</small>`:''}</dd></div>`).join('');}
function calculate(){
  const am=currentCalcMon('attacker'),dm=currentCalcMon('defender'),mv=MOVES.find(m=>m.name===$('#move-select').value);if(!am||!dm||!mv){$('#damage-percent').textContent='—';$('#damage-range').textContent='当前宝可梦没有可计算的攻击招式';$('#damage-bar').style.width='0';$('#ko-chip').textContent='无法计算';$('#move-info').textContent='请选择攻击方与招式';renderFactors([]);return;}if(!(mv.power>0)){$('#damage-percent').textContent='—';$('#damage-range').textContent='该招式的伤害取决于额外条件，暂不使用固定威力估算';$('#damage-bar').style.width='0';$('#ko-chip').textContent='需要专用参数';$('#move-info').innerHTML=`<b style="color:${typeColor(mv.type)}">${esc(zhMove(mv.name))}</b> · ${mv.type} · ${mv.category} · 威力随条件变化`;renderFactors([]);return;}
  const battle=calcState.battle,effectiveMove=moveInWeather(mv,battle.weather),moveType=effectiveMove.type,physical=effectiveMove.category==='物理',akey=effectiveMove.name==='Body Press'?'def':physical?'atk':'spa',dkey=physical?'def':'spd',factors=[];let power=effectiveMove.power,atk=championStat(am.stats[akey],calcState.attacker.points[akey],natureMod(calcState.attacker.nature,akey)),def=championStat(dm.stats[dkey],calcState.defender.points[dkey],natureMod(calcState.defender.nature,dkey));
  if(effectiveMove.weatherBallChanged)factors.push({label:'气象球',value:`威力 ${mv.power} → ${power}`,note:`属性 ${mv.type} → ${moveType}`});
  if(calcState.defender.item==='Assault Vest'&&!physical){def=Math.floor(def*1.5);factors.push({label:'突击背心',value:'特防 ×1.5'});}
  if(battle.weather==='sand'&&!physical&&dm.types.includes('岩石')){def=Math.floor(def*1.5);factors.push({label:'沙暴',value:'岩石系特防 ×1.5'});}
  if(battle.weather==='snow'&&physical&&dm.types.includes('冰')){def=Math.floor(def*1.5);factors.push({label:'下雪',value:'冰系防御 ×1.5'});}
  const hp=championStat(dm.stats.hp,calcState.defender.points.hp,1),type=dm.types.reduce((n,t)=>n*mult(moveType,t),1),stab=am.types.includes(moveType)?1.5:1,item=itemMod(calcState.attacker.item,effectiveMove,type),atkGrounded=isGrounded(am,calcState.attacker.item,battle.attackerGrounded),defGrounded=isGrounded(dm,calcState.defender.item,battle.defenderGrounded);let modifier=type*stab*item;
  factors.unshift({label:'属性克制',value:`${type}×`});if(stab!==1)factors.push({label:'本系加成',value:'1.5×'});if(item!==1)factors.push({label:zhItem(calcState.attacker.item),value:`${item}×`});
  if((battle.weather==='sun'&&moveType==='火')||(battle.weather==='rain'&&moveType==='水')){modifier*=1.5;factors.push({label:battle.weather==='sun'?'晴天':'雨天',value:'1.5×'});}else if((battle.weather==='sun'&&moveType==='水')||(battle.weather==='rain'&&moveType==='火')){modifier*=.5;factors.push({label:battle.weather==='sun'?'晴天':'雨天',value:'0.5×'});}
  if(atkGrounded&&((battle.terrain==='electric'&&moveType==='电')||(battle.terrain==='grassy'&&moveType==='草')||(battle.terrain==='psychic'&&moveType==='超能力'))){modifier*=1.3;factors.push({label:{electric:'电气场地',grassy:'青草场地',psychic:'精神场地'}[battle.terrain],value:'1.3×',note:'攻击方接地'});}
  if(battle.terrain==='misty'&&defGrounded&&moveType==='龙'){modifier*=.5;factors.push({label:'薄雾场地',value:'0.5×',note:'防守方接地'});}
  if(battle.terrain==='grassy'&&defGrounded&&['Earthquake','Bulldoze','Magnitude'].includes(mv.name)){modifier*=.5;factors.push({label:'青草场地',value:'0.5×',note:'地面震动招式'});}
  if(battle.burn&&physical){if(mv.name==='Facade'){power*=2;factors.push({label:'灼伤·硬撑',value:'威力 ×2',note:'不减半攻击'});}else{modifier*=.5;factors.push({label:'灼伤',value:'0.5×'});}}
  if(battle.critical){modifier*=1.5;factors.push({label:'暴击',value:'1.5×',note:(battle.reflect||battle.lightScreen||battle.auroraVeil)?'忽略墙':''});}
  const matchingWall=(physical&&battle.reflect)||(!physical&&battle.lightScreen)||battle.auroraVeil;if(matchingWall&&!battle.critical){const wall=battle.format==='Doubles'?2/3:.5;modifier*=wall;factors.push({label:battle.auroraVeil?'极光幕':physical?'反射壁':'光墙',value:`${wall===.5?'0.5':'0.667'}×`});}
  if(battle.helpingHand){modifier*=1.5;factors.push({label:'帮助',value:'1.5×'});}if(battle.friendGuard){modifier*=.75;factors.push({label:'友爱守护',value:'0.75×'});}if(battle.format==='Doubles'&&battle.target==='spread'){modifier*=.75;factors.push({label:'分散伤害',value:'0.75×'});}
  const raw=Math.floor(Math.floor(Math.floor(22*power*atk/Math.max(1,def))/50)+2),max=Math.max(0,Math.floor(raw*modifier)),min=Math.max(0,Math.floor(max*.85)),lo=min/hp*100,hi=max/hp*100;
  $('#damage-percent').textContent=type===0?'0':`${lo.toFixed(1)}–${hi.toFixed(1)}`;$('#damage-range').textContent=`伤害 ${min}–${max} / 总生命 ${hp}`;$('#damage-bar').style.width=Math.min(100,hi)+'%';$('#ko-chip').textContent=type===0?'无效':lo>=100?'确定一击击倒':hi>=100?'有概率一击击倒':lo>=50?'确定二击击倒':hi>=50?'有概率二击击倒':'至少三次攻击';$('#move-info').innerHTML=`<b style="color:${typeColor(moveType)}">${esc(zhMove(mv.name))}</b> · ${moveType} · ${mv.category} · 威力 ${power}<br>使用 ${STAT_LABELS[akey]} 对抗 ${STAT_LABELS[dkey]}`;renderFactors(factors);renderStats('attacker');renderStats('defender');
}
function syncBattleState(){
  const format=$('#calc-format').value,target=$('#target-mode');calcState.battle.format=format;if(format==='Singles'){target.value='single';target.disabled=true;}else target.disabled=false;calcState.battle.target=target.value;calcState.battle.weather=$('#weather-select').value;calcState.battle.terrain=$('#terrain-select').value;calcState.battle.attackerGrounded=$('#atk-grounded').value;calcState.battle.defenderGrounded=$('#def-grounded').value;calcState.battle.reflect=$('#mod-reflect').checked;calcState.battle.lightScreen=$('#mod-light-screen').checked;calcState.battle.auroraVeil=$('#mod-aurora-veil').checked;calcState.battle.burn=$('#mod-burn').checked;calcState.battle.critical=$('#mod-critical').checked;calcState.battle.helpingHand=$('#mod-helping-hand').checked;calcState.battle.friendGuard=$('#mod-friend-guard').checked;updateMoveOptions();calculate();
}
function resetBattle(){Object.assign(calcState.battle,{format:'Doubles',target:'single',weather:'none',terrain:'none',attackerGrounded:'auto',defenderGrounded:'auto',reflect:false,lightScreen:false,auroraVeil:false,burn:false,critical:false,helpingHand:false,friendGuard:false});$('#calc-format').value='Doubles';$('#target-mode').value='single';$('#target-mode').disabled=false;$('#weather-select').value='none';$('#terrain-select').value='none';$('#atk-grounded').value='auto';$('#def-grounded').value='auto';['reflect','light-screen','aurora-veil','burn','critical','helping-hand','friend-guard'].forEach(id=>$(`#mod-${id}`).checked=false);calculate();}
function refreshCalculator(){
  if(!store.calculator.length){renderPickerSelection('attacker');renderPickerSelection('defender');calculate();return;}
  ['attacker','defender'].forEach((side,sideIndex)=>{const preferred=side==='attacker'?'garchomp':'tyranitar';let index=store.calculator.findIndex(m=>m.slug===calcState[side].pokemonSlug);if(index<0)index=store.calculator.findIndex(m=>m.slug===preferred||m.name.toLowerCase()===preferred);if(index<0)index=store.calculator.findIndex(m=>speciesKey(m.name)===preferred);if(index<0)index=Math.min(sideIndex,store.calculator.length-1);calcState[side].pokemonIndex=index;calcState[side].pokemonSlug=store.calculator[index].slug;$(`#${sidePrefix(side)}-pokemon`).value=index;renderPickerSelection(side);if(pickerState[side].open)renderPickerList(side);});
  ['attacker','defender'].forEach(side=>{const prefix=sidePrefix(side),oldItem=calcState[side].item;fillSelect(`#${prefix}-item`,store.items,zhItem,x=>x);calcState[side].item=store.items.includes(oldItem)?oldItem:'No Item';$(`#${prefix}-item`).value=calcState[side].item;});updateMoveOptions();renderStats('attacker');renderStats('defender');calculate();
}
function setupCalc(){
  renderStatEditors();setupStatInputs();setupPicker('attacker');setupPicker('defender');fillSelect('#atk-nature',NATURES,zhNature,x=>x);fillSelect('#def-nature',NATURES,zhNature,x=>x);$('#atk-nature').value=calcState.attacker.nature;$('#def-nature').value=calcState.defender.nature;
  $('#atk-nature').addEventListener('change',event=>{calcState.attacker.nature=event.target.value;renderStats('attacker');calculate();});$('#def-nature').addEventListener('change',event=>{calcState.defender.nature=event.target.value;renderStats('defender');calculate();});$('#atk-item').addEventListener('change',event=>{calcState.attacker.item=event.target.value;calculate();});$('#def-item').addEventListener('change',event=>{calcState.defender.item=event.target.value;calculate();});$('#move-select').addEventListener('change',calculate);
  $$('#calc-format,#target-mode,#weather-select,#terrain-select,#atk-grounded,#def-grounded,#mod-reflect,#mod-light-screen,#mod-aurora-veil,#mod-burn,#mod-critical,#mod-helping-hand,#mod-friend-guard').forEach(control=>control.addEventListener('change',syncBattleState));$$('.reset-side[data-side]').forEach(button=>button.addEventListener('click',()=>resetPoints(button.dataset.side)));$('#reset-battle').addEventListener('click',resetBattle);document.addEventListener('pointerdown',event=>{['attacker','defender'].forEach(side=>{if(pickerState[side].open&&!$(`#${sidePrefix(side)}-picker`).contains(event.target))closePicker(side);});});renderStats('attacker');renderStats('defender');
}

async function initializeApp(){
  const requested=location.hash.slice(1),initial=['usage','types','calc'].includes(requested)?requested:'usage';showUsageSkeleton();showCalcSkeleton();$$('.nav-btn').forEach(b=>b.onclick=()=>navTo(b.dataset.view));window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['usage','types','calc'].includes(view)&&currentView()!==view)navTo(view);});$('#usage-search').addEventListener('input',e=>renderRanking(e.target.value));$('#format-select').addEventListener('change',()=>{const format=$('#format-select').value;$('#format-label').textContent=format==='Doubles'?'双打':'单打';void ensureViewData('usage');});$('#refresh-data').addEventListener('click',()=>updateData());$('#config-backdrop').addEventListener('click',()=>closeConfigDrawer());$('#config-panel').addEventListener('keydown',trapConfigFocus);mobileConfigQuery.addEventListener?.('change',event=>{if(!event.matches)closeConfigDrawer({returnFocus:false});});navTo(initial);
  const payload=await fetchJSON(`/api/bootstrap?v=${API_REVISION}`);hydrateStatic(payload.static);calcState=createCalcState();setupTypes();setupCalc();commonReady=true;applyMeta(payload.meta);if(payload.meta){await ensureViewData(initial);schedulePrefetch();}else setStatus('SQLite 已初始化，但尚无赛季数据。请点击“更新赛季数据”。','warn');setupModelTools();
}
initializeApp().catch(error=>{console.error(error);setStatus(`无法读取本地数据库：${error.message}`,'error');showViewError(currentView(),`无法初始化公共数据：${error.message}`,()=>location.reload());});

function setupModelTools(){if(document.modelContext?.registerTool){
  document.modelContext.registerTool({name:'find_pokemon_meta',description:'Find a Pokémon in the currently loaded Pokémon Champions Battle Data ranking and return its rank and common configuration.',inputSchema:{type:'object',properties:{name:{type:'string',description:'Chinese or English Pokémon name, including a partial name'}},required:['name']},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:({name})=>{const q=String(name).toLowerCase(),format=$('#format-select').value,i=ranking.findIndex(m=>m.name.toLowerCase().includes(q)||m.displayName.includes(name));if(i<0)return `当前${format==='Doubles'?'双打':'单打'}前 50 名中没有找到“${name}”。`;const m=ranking[i],b=m.battles[format],top=b.top||{};navTo('usage');renderRanking(m.displayName);selectConfig(i);return `${m.displayName}：${format==='Doubles'?'双打':'单打'}使用排名第 ${b.position}，常用道具 ${zhItem(top.held_item?.name)}${pct(top.held_item)}，常用招式 ${zhMove(top.move?.name)}${pct(top.move)}，性格 ${zhNature(top.stat_alignment?.name)}${pct(top.stat_alignment)}。数据赛季 ${store.meta.season}。`;}}).catch(()=>{});
  document.modelContext.registerTool({name:'refresh_champions_data',description:'Refresh Pokémon Champions season data from the configured third-party Battle Data mirror.',inputSchema:{type:'object',properties:{}},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async()=>{await updateData();return $('#update-status').textContent;}}).catch(()=>{});
  document.modelContext.registerTool({name:'check_type_matchup',description:'Calculate one attacking type against a one- or two-type defender.',inputSchema:{type:'object',properties:{attackType:{type:'string',enum:TYPES},defenseType1:{type:'string',enum:TYPES},defenseType2:{type:'string',enum:['',...TYPES]}},required:['attackType','defenseType1']},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:({attackType,defenseType1,defenseType2=''})=>{const value=[defenseType1,defenseType2].filter(Boolean).reduce((n,d)=>n*mult(attackType,d),1);return `${attackType}属性攻击 ${defenseType1}${defenseType2?'／'+defenseType2:''} 属性防守方时为 ${value} 倍。`;}}).catch(()=>{});
}}
